package com.booksyde.controller; import com.booksyde.dto.response.PublisherDashboardResponse; import com.booksyde.exception.ForbiddenException; import com.booksyde.security.BooksydeRole; import com.booksyde.service.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/publishers") public class PublisherController {private final PublisherService publishers; private final AuthenticatedUserService users; public PublisherController(PublisherService publishers,AuthenticatedUserService users){this.publishers=publishers;this.users=users;} @GetMapping("/me/dashboard") public PublisherDashboardResponse dashboard(@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);if(!(u.roles().contains(BooksydeRole.PUBLISHER)||u.roles().contains(BooksydeRole.CREATOR)||u.roles().contains(BooksydeRole.ADMIN))) throw new ForbiddenException("Conta sem acesso ao painel editorial.");return publishers.dashboard(u.id());}}
